	fmt.Println("| --- | --- |")
	for _, row := range [][2]string{{"A|B", `C:\docs`}, {"中文", "first\nsecond"}} {
		fmt.Printf("| %s | %s |\n", escape(row[0]), escape(row[1]))
	}
}

